  meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, image_url=excluded.image_url, og_image=excluded.og_image, updated_at=now()
returning slug, published, length(content) as len, md5(content) as md5;

insert into public.articles (lang, translation_of, slug, title, perex, content, meta_title, meta_description, focus_keyword, category_id, author_id, image_url, og_image, published)
values ('pl', null, $pl$kopenhaga-z-dziecmi$pl$, $pl$Kopenhaga z dziećmi: co robić według wieku i ile to kosztuje$pl$, $pl$Sprawdź, co robić w Kopenhadze z dziećmi w zależności od wieku, gdzie się schować przed deszczem i co jest za darmo. Policzyliśmy też, czy Copenhagen Card w ogóle opłaca się rodzinie, i sprawdziliśmy, jak jeździć komunikacją miejską z dziećmi i wózkiem.$pl$, $pl$<p>Samolot wylądował w&nbsp;Kastrupie, bagaże już krążą na taśmie, a&nbsp;starsze dziecko pyta, czy dziś będzie padać. Sprawdzasz pogodę w&nbsp;telefonie: deszcz do południa. Młodsze dziecko domaga się jedzenia, więc pierwsza rzecz, jaką kupujesz w&nbsp;Danii, to hot dog przy stacji metra na lotnisku. I&nbsp;od razu pierwszy cenowy szok tego wyjazdu.</p>
<p><strong>Ceny sprawdzone 28 września 2026</strong>, w&nbsp;koronach duńskich (DKK, czasem zapisywanych jako kr.), bez przeliczeń na złote.</p>
<p><em>Zdjęcie tytułowe: Den Blå Planet w&nbsp;Kastrup. Zdjęcie archiwalne, 2017. Fot. <a href="https://commons.wikimedia.org/wiki/File:National_Aquarium_Denmark,_Kastrup,_Denmark_(Unsplash).jpg">Sandro Katalina sandrokatalina</a>, <a href="http://creativecommons.org/publicdomain/zero/1.0/deed.en">CC0</a>. Pomniejszone i przekonwertowane do formatu WebP.</em></p>
<h2>Co robić z&nbsp;dziećmi w&nbsp;zależności od wieku</h2>
<h3>Niemowlęta i&nbsp;maluchy (0–3 lata)</h3>
<p>Z&nbsp;najmłodszym dzieckiem szukasz przede wszystkim miejsca, gdzie maluch może się swobodnie ruszać, a&nbsp;Ty nie musisz go pilnować co chwilę.</p>
<ul><li><strong>Den Blå Planet</strong>, duńskie akwarium narodowe, stoi ok. 600 metrów (ok. 10 minut pieszo) od stacji metra Kastrup – dobry pierwszy albo ostatni przystanek w&nbsp;podróży. Budynek ma windy i&nbsp;platformy (nie wszędzie jest to jednak w&nbsp;pełni bezbarierowe) oraz bezpłatne wózki inwalidzkie do wypożyczenia po wcześniejszej rezerwacji, najpóźniej dzień przed wizytą. Dotykowy basen z&nbsp;płaszczkami i&nbsp;rozgwiazdami lubią też najmłodsi. Bilet dla dorosłego kosztuje 249&nbsp;DKK (online 219&nbsp;DKK), bilet dziecięcy (3–11 lat) 131&nbsp;DKK (online 116&nbsp;DKK), a&nbsp;dzieci do 2 lat wchodzą za darmo. W&nbsp;weekendy i&nbsp;w&nbsp;szczycie sezonu ceny są nieco wyższe (259 i&nbsp;136&nbsp;DKK, online 229 i&nbsp;123&nbsp;DKK). Więcej o&nbsp;samym Kastrupie i&nbsp;pobliskiej plaży piszemy w&nbsp;<a href="/artykul/kastrup">osobnym artykule</a>.</li><li><strong>Experimentarium</strong> w&nbsp;Hellerup ma osobną strefę zabaw Miniverset, pomyślaną dla dzieci od 1 do 5 lat. Bilety online: 230&nbsp;DKK od 12 lat, 143&nbsp;DKK dla dzieci 2–11 lat, młodsze wchodzą za darmo; ceny zależą od dnia.</li><li><strong>Islands Brygge Havnebad</strong> latem – płytki basenik dla najmłodszych (Småbørnsbassin, 18×6&nbsp;m, głębokość 10–70&nbsp;cm), wstęp wolny; ratownik dyżuruje tylko od 1 czerwca do 31 sierpnia, 10–18. Jakość wody sprawdzisz na kk.dk; jeśli stojąc po kolana nie widzisz stóp, lepiej nie wchodzić.</li></ul>
<h3>Przedszkolaki (4–7 lat)</h3>
<p>W&nbsp;tym wieku dzieci chcą wszystko robić same, więc sprawdzają się miejsca, gdzie można się wybiegać i&nbsp;coś zbudować.</p>
<figure><img src="https://kastrup.cz/images/clanky/kopenhaga-z-dziecmi/rundetaarn-rampa-1500.webp" alt="Spiralna rampa wewnątrz wieży Rundetaarn w Kopenhadze" loading="lazy"><figcaption>Rampa w&nbsp;Rundetaarn. Zdjęcie archiwalne, 2011. Fot. <a href="https://commons.wikimedia.org/wiki/File:002_Copenhagen_landmark_-_The_Round_Tower_(Rundetaarn)_spiral_ramp.jpg">Marek Ślusarczyk (Tupungato) Photo portfolio</a>, <a href="https://creativecommons.org/licenses/by/3.0">CC BY 3.0</a>. Pomniejszone i przekonwertowane do formatu WebP.</figcaption></figure>
<ul><li><strong>Rundetaarn</strong> – dzieci poniżej 18 lat wchodzą za darmo (dorosły płaci 60&nbsp;DKK, bilet tylko na miejscu), a&nbsp;na szczyt nie prowadzą schody, tylko spiralna rampa (7,3 obrotu, 281 metrów, nachylenie 10%), po której da się iść albo biec. Dzieci do 11 lat muszą iść z&nbsp;dorosłym. Ostatni odcinek na platformę to wąskie, kręte schody.</li><li><strong>Tårnlegepladsen</strong> w&nbsp;Fælledparku – plac zabaw z&nbsp;miniaturami kopenhaskich wież (m.in. wieży Vor Frelsers Kirke, ratusza i&nbsp;Rundetaarn) połączonych kładkami i&nbsp;zjeżdżalniami. W&nbsp;dni powszednie dyżurują tu pedagodzy, a&nbsp;toaleta i&nbsp;przewijak są dostępne także poza tymi godzinami.</li><li><strong>Experimentarium</strong>, strefa Legedalen (3–6 lat).</li><li><strong>LEGO Store</strong> przy Vimmelskaftet 37 na Strøget – ściana Pick &amp; Build i&nbsp;stanowisko do budowania własnej minifigurki, otwarte pon.–sob. 10–18, w&nbsp;niedziele 11–17.</li></ul>
<h3>Starsze dzieci (8–12 lat)</h3>
<figure><img src="https://kastrup.cz/images/clanky/kopenhaga-z-dziecmi/zoo-wieza-wielblad-1500.webp" alt="Wielbłąd na wybiegu i wieża widokowa w zoo w Kopenhadze" loading="lazy"><figcaption>Zoo w&nbsp;Kopenhadze z&nbsp;wieżą widokową. Zdjęcie archiwalne, 2012. Fot. <a href="https://commons.wikimedia.org/wiki/File:Copenhagen_Zoo_Tower_and_camel.jpg">Guillaume Baviere from Helsingborg, Sweden</a>, <a href="https://creativecommons.org/licenses/by/2.0">CC BY 2.0</a>. Pomniejszone i przekonwertowane do formatu WebP.</figcaption></figure>
<ul><li><strong>Zoo København</strong> (Roskildevej 32, Frederiksberg) – bilet dla dorosłego 260&nbsp;DKK, dziecięcy (3–14 lat) 160&nbsp;DKK, ważny rok od zakupu; ceny zmieniają się w&nbsp;zależności od sezonu. Wejście na Zootårnet, wieżę widokową w&nbsp;zoo, kosztuje dodatkowo 25&nbsp;DKK. W&nbsp;październiku zoo jest otwarte codziennie 9–17, od listopada do lutego krócej, 10–16.</li><li><strong>Nationalmuseet i&nbsp;Børnenes Museum</strong> – dzieci poniżej 18 lat wchodzą za darmo, dorosły płaci 150&nbsp;DKK (online 135&nbsp;DKK). W&nbsp;dziecięcej części czeka wikińska łódź Fafner ze strojami do przebierania, pakistański bazar i&nbsp;średniowieczny zamek. Børnenes Museum zamyka się o&nbsp;16.30, pół godziny wcześniej niż reszta muzeum. Muzeum jest zamknięte 24, 25 i&nbsp;31 grudnia.</li><li><strong>Rejs po kanałach</strong> – Netto-Bådene z&nbsp;Nyhavn (dorosły 80&nbsp;DKK, dziecko 3–14 lat 40&nbsp;DKK, bez rezerwacji) albo Stromma (z&nbsp;Nyhavn od 169&nbsp;DKK za dorosłego, dzieci 6–15 lat płacą połowę, młodsze płyną za darmo).</li></ul>
<h2>Kiedy pada deszcz</h2>
<p>W&nbsp;Kopenhadze jest parę miejsc, w&nbsp;których przesiedzisz kilka godzin bez patrzenia na niebo.</p>
<figure><img src="https://kastrup.cz/images/clanky/kopenhaga-z-dziecmi/experimentarium-1500.webp" alt="Budynek centrum nauki Experimentarium w Hellerup" loading="lazy"><figcaption>Experimentarium w&nbsp;Hellerup. Zdjęcie archiwalne. Fot. <a href="https://commons.wikimedia.org/wiki/File:20171005_Experimentarium_Hellerup_0062_(37729624156).jpg">Johan Wessman / News Oresund</a>, <a href="https://creativecommons.org/licenses/by/2.0">CC BY 2.0</a>. Pomniejszone i przekonwertowane do formatu WebP.</figcaption></figure>
<p><strong>Den Blå Planet</strong> i&nbsp;<strong>Experimentarium</strong> (otwarte codziennie 9.30–17 przez cały rok, 24 i&nbsp;31 grudnia tylko do 14) to najpewniejsze opcje. <strong>Nationalmuseet z&nbsp;Børnenes Museum</strong> też się sprawdzi, ale od listopada do marca jest zamknięte w&nbsp;poniedziałki. LEGO Store starczy na jakieś pół godziny, ale jako przerwa w&nbsp;środku spaceru się sprawdza.</p>
<h2>Co jest za darmo</h2>
<figure><img src="https://kastrup.cz/images/clanky/kopenhaga-z-dziecmi/islands-brygge-kapielisko-1500.webp" alt="Kąpielisko portowe Islands Brygge latem pełne ludzi" loading="lazy"><figcaption>Islands Brygge Havnebad, lipiec 2026. Fot. <a href="https://commons.wikimedia.org/wiki/File:Islands_Brygge_Havnebad_K%C3%B8benhavn.jpeg">kallerna</a>, <a href="https://creativecommons.org/licenses/by-sa/4.0">CC BY-SA 4.0</a>. Pomniejszone i przekonwertowane do formatu WebP.</figcaption></figure>
<p>Kilka rzeczy w&nbsp;Kopenhadze naprawdę nic nie kosztuje: wejście na <strong>Rundetaarn</strong> dla dzieci poniżej 18 lat, wstęp do <strong>Nationalmuseet i&nbsp;Børnenes Museum</strong> dla osób poniżej 18 lat (dorosły płaci 150&nbsp;DKK), publiczny plac zabaw <strong>Tårnlegepladsen</strong> w&nbsp;Fælledparku, bez biletów i&nbsp;bramek, oraz kąpielisko <strong>Islands Brygge Havnebad</strong>, otwarte codziennie 6–22 przez cały rok.</p>
<h2>Czy opłaca się Copenhagen Card dla rodziny</h2>
<p>Copenhagen Card kupisz w&nbsp;wariancie Discover (z&nbsp;komunikacją miejską w&nbsp;całym regionie, także z&nbsp;lotniska) albo Hop (bez komunikacji miejskiej, ale z&nbsp;autobusami hop-on hop-off). Ceny Discover na 24 godziny: dorosły (od 16 lat) 589&nbsp;DKK, junior (12–15 lat) 399&nbsp;DKK, dziecko (3–11 lat, „Kids”) 100&nbsp;DKK; najwyżej dwie karty Kids na jedną kartę dorosłego, kupione w&nbsp;tym samym zamówieniu, inaczej ich nie dokupisz. Na pytanie, czy dzieci dostają kartę gratis, operator odpowiada w&nbsp;FAQ krótko: nie. Dzieci do 2 lat w&nbsp;ogóle jej nie potrzebują.</p>
<figure><img src="https://kastrup.cz/images/clanky/kopenhaga-z-dziecmi/nationalmuseet-1500.webp" alt="Gmach Nationalmuseet nad kanałem w centrum Kopenhagi" loading="lazy"><figcaption>Nationalmuseet. Zdjęcie archiwalne, 2018. Fot. <a href="https://commons.wikimedia.org/wiki/File:Nationalmuseet_20180721.jpg">Suicasmo</a>, <a href="https://creativecommons.org/licenses/by-sa/4.0">CC BY-SA 4.0</a>. Pomniejszone i przekonwertowane do formatu WebP.</figcaption></figure>
<p>Ważne zastrzeżenie: <strong>Rundetaarn nie jest objęty Copenhagen Card</strong>. Od 1 kwietnia 2024 wieża wypadła z&nbsp;listy atrakcji karty – mówi o&nbsp;tym wprost strona wieży. Jeśli w&nbsp;planie masz właśnie Rundetaarn, dolicz do niego osobny bilet, karta go nie pokryje.</p>
<p>Policzmy to na przykładzie dwóch atrakcji, które karta rzeczywiście obejmuje: rodzina 2+2, dzieci w&nbsp;wieku 5 i&nbsp;9 lat, jeden dzień w&nbsp;mieście z&nbsp;Zoo i&nbsp;Experimentarium. Bilety osobno: do zoo (2 × 260 + 2 × 160 = 840&nbsp;DKK) i&nbsp;do Experimentarium (online 2 × 230 + 2 × 143 = 746&nbsp;DKK, cena zależy od dnia) dają razem 1586&nbsp;DKK. Copenhagen Card Discover na 24 godziny dla tej samej rodziny (2 × 589 + 2 × 100) kosztuje 1378&nbsp;DKK, czyli o&nbsp;208&nbsp;DKK mniej, jeszcze bez liczenia przejazdów.</p>
<p>Do transportu dwoje dzieci poniżej 12 lat jedzie z&nbsp;dorosłym za darmo na dowolny bilet, nie tylko na City Pass, więc doliczasz jedynie bilety dla dorosłych. Trzy przejazdy w&nbsp;dwóch strefach (2 × 24&nbsp;DKK za każdy) to kolejne 144&nbsp;DKK, razem 1730&nbsp;DKK bez karty. Wtedy Copenhagen Card z&nbsp;komunikacją miejską w&nbsp;cenie (1378&nbsp;DKK) wychodzi taniej o&nbsp;352&nbsp;DKK. Oficjalna strona zastrzega, że ceny mogą się zmienić bez zapowiedzi, więc przelicz to jeszcze raz tuż przed wyjazdem.</p>
<h2>Komunikacja miejska z&nbsp;dziećmi i&nbsp;wózkiem</h2>
<p>Dzieci do 15 lat płacą za bilet jednorazowy połowę ceny dorosłego, ale dwoje dzieci poniżej 12 lat jedzie z&nbsp;dorosłym za darmo na dowolny bilet, nie tylko na City Pass – to ogólna zasada DOT, nie przywilej samego City Passu. Bilet na dwie strefy kosztuje 24&nbsp;DKK, na trzy strefy (czyli na przykład z&nbsp;lotniska do centrum) 30&nbsp;DKK i&nbsp;jest ważny półtorej godziny; metro M2 z&nbsp;lotniska do centrum jedzie 14 minut. City Pass ma sens raczej wtedy, gdy jeździcie dużo tego samego dnia i&nbsp;nie chcecie za każdym razem kupować pojedynczych biletów; dzieci 12–15 lat płacą na niego połowę ceny. Szczegóły dojazdu, cen i&nbsp;nocnych kursów opisaliśmy w&nbsp;<a href="/artykul/lotnisko-kopenhaga-dojazd-do-centrum">przewodniku po lotnisku Kastrup</a>.</p>
<p>Windy podaje strona przewoźnika m.dk przy wszystkich 44 stacjach metra, od jednej (Kastrup) po sześć (Kongens Nytorv) – z&nbsp;wózkiem wejdziesz więc bez większego problemu. Na łódź Stromma wózka nie wniesiesz – przewoźnik wprost pisze, że to niemożliwe. Wózek możesz zostawić na nabrzeżu na własne ryzyko, przewoźnik radzi przypiąć go własnym zapięciem. Na łodziach nie ma też toalety.</p>
<h2>Co jest sezonowe i&nbsp;co zimą zamknięte</h2>
<p>Łodzie Netto-Bådene pływają cały rok (od października do marca kryte i&nbsp;ogrzewane), ale przy zamarzniętym porcie nie kursują wcale – w&nbsp;2026 roku wznowiły kursy dopiero 5 marca, gdy port rozmarzł. Według strony wieży obserwatorium na szczycie Rundetaarn jest w&nbsp;2026 roku zamknięte z&nbsp;powodu renowacji, choć w&nbsp;sklepie z&nbsp;biletami wciąż widnieją terminy wieczornych obserwacji. Jeśli na nie liczysz, zapytaj w&nbsp;kasie.</p>
<h2>Czego lepiej unikać</h2>
<ul><li>Kupowania Copenhagen Card tylko dla dorosłych w&nbsp;przekonaniu, że dzieci wejdą z&nbsp;wami za darmo – dziecko 3–11 lat potrzebuje karty Kids, którą trzeba dokupić w&nbsp;tym samym zamówieniu co kartę dorosłego (100&nbsp;DKK za 24 godziny).</li><li>Liczenia na to, że Copenhagen Card pokryje Rundetaarn – od 2024 roku wieża wypadła z&nbsp;listy atrakcji karty, bilet trzeba dokupić osobno.</li><li>Przyjazdu do Nationalmuseet w&nbsp;poniedziałek między listopadem a&nbsp;marcem – wtedy muzeum jest zamknięte, poza jednym tygodniem w&nbsp;lutym i&nbsp;Wielkanocą.</li><li>Liczenia na rejs Netto-Bådene w&nbsp;mroźny dzień – przy zamarzniętym porcie łodzie nie wypływają.</li><li>Planu wizyty w&nbsp;Tivoli na przełomie września i&nbsp;października albo na początku listopada – akurat wtedy ogrody stoją zamknięte między sezonami.</li></ul>
<h2>Tivoli i&nbsp;Legoland, jeśli zostanie Ci czas</h2>
<p>Jeśli w&nbsp;planie masz też Ogrody Tivoli, sprawdź najpierw kalendarz sezonów i&nbsp;limity wzrostu na atrakcjach w&nbsp;naszym <a href="/artykul/tivoli-kopenhaga">przewodniku po Tivoli</a>. Między sezonami park stoi zamknięty: do 1 października i&nbsp;od 2 do 12 listopada 2026. Legoland w&nbsp;Billund leży w&nbsp;środku Jutlandii, po drugiej stronie kraju niż Kopenhaga, więc to raczej osobny wyjazd niż dodatek do jednego dnia w&nbsp;mieście; ceny biletów i&nbsp;kalendarz otwarcia opisaliśmy w&nbsp;<a href="/artykul/legoland-dania">przewodniku po Legolandzie</a>.</p>
<figure><img src="https://kastrup.cz/images/clanky/kopenhaga-z-dziecmi/rejs-kanalami-1500.webp" alt="Łódź wycieczkowa płynąca kanałem w Kopenhadze" loading="lazy"><figcaption>Łódź z&nbsp;rejsami po kanałach. Zdjęcie archiwalne, 2015. Fot. <a href="https://commons.wikimedia.org/wiki/File:Canal_Tours_in_Nyhavn_01.JPG">Leif Jørgensen</a>, <a href="https://creativecommons.org/licenses/by-sa/4.0">CC BY-SA 4.0</a>. Pomniejszone i przekonwertowane do formatu WebP.</figcaption></figure>
<p>Jeśli dopiero układasz resztę trasy, zerknij też do naszego <a href="/kopenhaga">przewodnika po Kopenhadze</a> i&nbsp;<a href="/noclegi">zestawienia noclegów</a> blisko centrum.</p>
<h2>Najczęściej zadawane pytania</h2>
<p><strong>Czy Copenhagen Card opłaca się rodzinie z&nbsp;dziećmi?</strong> Częściej, niż mogłoby się wydawać, ale nie zawsze. W&nbsp;naszym przykładzie (rodzina 2+2, bilety do zoo i&nbsp;Experimentarium plus kilka przejazdów komunikacją miejską) osobne bilety kosztują 1730&nbsp;DKK, karta 1378&nbsp;DKK – oszczędzasz 352&nbsp;DKK. Uważaj tylko na Rundetaarn: karta go nie obejmuje, tam dopłacisz osobno. Policz to dla swojego planu.</p>
<p><strong>Co robić z&nbsp;dziećmi w&nbsp;Kopenhadze, gdy pada deszcz?</strong> Den Blå Planet, Experimentarium i&nbsp;Nationalmuseet z&nbsp;Børnenes Museum mają dachy nad głową na kilka godzin. Experimentarium jest otwarte codziennie przez cały rok, a&nbsp;Nationalmuseet od listopada do marca bywa zamknięte w&nbsp;poniedziałki.</p>
<p><strong>Czy dzieci jeżdżą kopenhaską komunikacją za darmo?</strong> Częściowo. Na bilet jednorazowy dwoje dzieci poniżej 12 lat jedzie z&nbsp;dorosłym za darmo – to ogólna zasada, nie tylko City Passu. Starsze i&nbsp;kolejne dzieci płacą połowę ceny dorosłego.</p>
<p><strong>Czy z&nbsp;wózkiem wejdę na wieżę Rundetaarn?</strong> Częściowo. Rampą da się wjechać, ale to 281 metrów pod górę ze spadkiem 10%, a&nbsp;na sam taras widokowy prowadzą już tylko wąskie schody. Oficjalna strona wieży pisze, że miejsce nie nadaje się dobrze dla wózków.</p>
<p><strong>Co w&nbsp;Kopenhadze jest dla dzieci za darmo?</strong> Wieża Rundetaarn dla dzieci poniżej 18 lat, wstęp do Nationalmuseet i&nbsp;Børnenes Museum dla osób poniżej 18 lat (dorosły płaci 150&nbsp;DKK), plac zabaw Tårnlegepladsen w&nbsp;Fælledparku i&nbsp;kąpielisko Islands Brygge Havnebad, otwarte cały rok.</p>
<p><strong>Źródła:</strong> zoo.dk i&nbsp;shop.zoo.dk (Zoo København), experimentarium.dk (Experimentarium), nationalmuseet.dk (Nationalmuseet, Børnenes Museum), rundetaarn.dk (Rundetaarn), lego.com (LEGO Store), legeplads.kk.dk (Tårnlegepladsen), copenhagencard.com (Copenhagen Card), havnerundfart.dk i&nbsp;stromma.com (rejsy po kanałach), svoemkbh.kk.dk (Islands Brygge Havnebad), m.dk i&nbsp;dinoffentligetransport.dk (komunikacja miejska, windy w&nbsp;metrze, dzieci w&nbsp;komunikacji), tivoli.dk i&nbsp;shop.tivoli.dk (Ogrody Tivoli). Ceny i&nbsp;godziny sprawdzone 28 września 2026.</p>$pl$, $pl$Kopenhaga z dziećmi: atrakcje i ceny 2026 | Kastrup.pl$pl$, $pl$Kopenhaga z dziećmi: atrakcje według wieku, co robić w deszczu, co jest za darmo i czy opłaca się Copenhagen Card. Ceny sprawdzone 28 września 2026.$pl$, $pl$kopenhaga z dziećmi$pl$, 'cbf723ca-1307-4ffd-8717-5b673c8643cd', '415c2012-9d88-4267-9b21-63b93ab384ad', $pl$https://kastrup.cz/images/clanky/kopenhaga-z-dziecmi/den-bla-planet-1500.webp$pl$, $pl$https://kastrup.cz/images/clanky/kopenhaga-z-dziecmi/den-bla-planet-1500.webp$pl$, false)
on conflict (lang, slug) do update set title=excluded.title, perex=excluded.perex, content=excluded.content, meta_title=excluded.meta_title,
  meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, image_url=excluded.image_url, og_image=excluded.og_image, updated_at=now()
returning slug, published, length(content) as len, md5(content) as md5;
